<?php if($page==='success'): ?><div class="success-receipt" role="status"><span><?=mdi('check-circle-outline')?></span><div><h2>Servis terkirim</h2><p>Nomor invoice Anda: <strong><?=e($order['invoice_number'])?></strong></p></div></div><?php endif; ?>
<div class="page-heading"><div><h1 class="invoice-title"><?=e($order['invoice_number'])?></h1><p class="muted">Diterbitkan <?=e(human_date($order['issued_on']))?> · <?=e($order['location'])?></p></div><div class="button-group"><?php if($user['role']==='admin'): ?><a class="button secondary" href="<?=e(url('service-edit',['id'=>$order['id']]))?>">Edit servis</a><?php endif; ?><a class="button" href="<?=e(url('invoice',['id'=>$order['id']]))?>">Cetak invoice <?=mdi('arrow-top-right')?></a></div></div>
<div class="detail-grid"><section class="panel detail-panel"><div class="panel-heading"><h2>Perangkat & konsumen</h2><?=badge($order['status'])?></div><div class="detail-device"><span><?=mdi('television')?></span><div><h2><?=e($order['item_name'])?></h2><p><?=e($order['brand'].' · '.$order['model'])?></p></div></div><dl class="detail-list"><?php foreach(['Nama konsumen'=>$order['customer_name'],'Nomor HP'=>$order['contact_phone'],'Alamat'=>$order['address'],'Tanggal masuk'=>human_date($order['received_date']),'Serial number'=>$order['serial_number']?:'-','Kelengkapan'=>implode(', ',json_decode($order['accessories'],true))?:'-','Keluhan / kerusakan'=>$order['complaint'],'Catatan konsumen'=>$order['notes']?:'-','Catatan teknisi'=>$order['technician_notes']?:'-'] as $label=>$value): ?><div><dt><?=e($label)?></dt><dd><?=nl2br(e($value))?></dd></div><?php endforeach; ?></dl></section><aside><section class="panel summary-panel"><h3>Pengerjaan</h3><dl class="detail-list"><div><dt>Selesai service</dt><dd><?=e(human_date($order['completed_date']))?></dd></div><div><dt>Garansi sampai</dt><dd><?=e(human_date($order['warranty_date']))?></dd></div></dl><div class="cost-block"><span>Total biaya</span><strong data-testid="total-cost"><?=e(money($order['total_cost']))?></strong><small><?=$order['total_cost']===null?'Belum ditetapkan':''?></small></div></section></aside></div>
<?php if($user['role']==='admin'): ?><section class="panel form-panel"><div class="section-heading"><span><?=mdi('package-variant-closed')?></span><div><h2>Penggunaan sparepart</h2><p>Isi 0 untuk mengembalikan stok.</p></div></div>
<?php if($order['status']==='Dibatalkan'): ?><div class="notice">Servis dibatalkan. Seluruh alokasi aktif telah dikembalikan. Ubah status servis untuk memakai sparepart kembali.</div><?php endif; ?>
<?php if($parts): ?><div class="allocation-list"><?php foreach($parts as $part): ?><form method="post" action="<?=e(url('service-edit',['id'=>$order['id']]))?>" class="allocation-row"><?=csrf()?><input type="hidden" name="action" value="allocate"><input type="hidden" name="part_id" value="<?=e($part['spare_part_id'])?>"><input type="hidden" name="expected" value="<?=e($part['quantity'])?>"><div><strong><?=e($part['name'])?></strong><small><?=e($part['sku'])?> · Tersedia <?=e($part['stock'].' '.$part['unit'])?></small></div><label class="field"><span>Jumlah (<?=e($part['unit'])?>)</span><input type="number" name="quantity" min="0" max="1000000000" step="1" value="<?=e($part['quantity'])?>" required></label><button class="button secondary" <?=$order['status']==='Dibatalkan'?'disabled':''?>>Simpan jumlah</button></form><?php endforeach; ?></div><?php endif; ?>
<?php $unallocated=array_filter($available,fn($part)=>(int)$part['allocated']===0); if($unallocated && $order['status']!=='Dibatalkan'): ?><form method="post" action="<?=e(url('service-edit',['id'=>$order['id']]))?>" class="inline-form"><?=csrf()?><input type="hidden" name="action" value="allocate"><input type="hidden" name="expected" value="0"><label class="field grow"><span>Tambahkan sparepart</span><select name="part_id" required><option value="">Pilih komponen</option><?php foreach($unallocated as $part): ?><option value="<?=e($part['id'])?>"><?=e($part['sku'].' · '.$part['name'].' — stok '.$part['stock'].' '.$part['unit'])?></option><?php endforeach; ?></select></label><label class="field quantity-field"><span>Jumlah</span><input name="quantity" type="number" min="1" max="1000000000" required value="1"></label><button class="button">Gunakan sparepart</button></form><?php elseif(!$available): ?><p class="muted">Belum ada sparepart. <a href="<?=e(url('part-new'))?>">Tambah sparepart</a> terlebih dahulu.</p><?php endif; ?></section><?php endif; ?>
